      function render() {
        const filter = getFilter();
        const active = todos.filter(todo => !todo.completed).length;
        const visible = todos.filter(todo => filter === 'all' || (filter === 'completed' ? todo.completed : !todo.completed));
        list.replaceChildren();
        for (const todo of visible) {
          const row = document.createElement('li');
          row.className = 'todo' + (todo.completed ? ' completed' : '');
          row.dataset.id = todo.id;
          const checkbox = document.createElement('input');
          checkbox.type = 'checkbox';
          checkbox.checked = todo.completed;
          checkbox.setAttribute('aria-label', `Mark "${todo.title}" ${todo.completed ? 'active' : 'complete'}`);
          checkbox.addEventListener('change', () => {
            todo.completed = checkbox.checked;
            const index = visible.indexOf(todo);
            save(todo.completed ? 'Todo completed.' : 'Todo marked active.');
            const next = Array.from(list.children).find(item => item.dataset.id === todo.id) || list.children[Math.min(index, list.children.length - 1)];
            (next ? next.querySelector('input') : input).focus();
          });
          const label = document.createElement('span');
          label.className = 'todo-text';
          label.textContent = todo.title;
          label.tabIndex = 0;
          label.title = 'Double-click or press Enter to edit';
          label.addEventListener('dblclick', () => editTodo(todo, row));
          label.addEventListener('keydown', event => {
            if (event.key === 'Enter' || event.key === 'F2') {
              event.preventDefault();
              editTodo(todo, row);
            }
          });
          const remove = document.createElement('button');
          remove.type = 'button';
          remove.className = 'delete';
          remove.textContent = '\u00d7';
          remove.setAttribute('aria-label', `Delete "${todo.title}"`);
          remove.addEventListener('click', () => {
            const index = visible.indexOf(todo);
            todos = todos.filter(item => item.id !== todo.id);
            save('Todo deleted.');
            const next = list.children[Math.min(index, list.children.length - 1)];
            (next ? next.querySelector('.delete') : input).focus();
          });
          row.append(checkbox, label, remove);
          list.append(row);
        }
        document.querySelector('#count').replaceChildren();
        const number = document.createElement('strong');
        number.textContent = active;
        document.querySelector('#count').append(number, ` ${active === 1 ? 'item' : 'items'} left`);
        toggleAll.disabled = todos.length === 0;
        toggleAll.checked = todos.length > 0 && active === 0;
        toggleAll.indeterminate = active > 0 && active < todos.length;
        clearButton.disabled = !todos.some(todo => todo.completed);
        document.querySelectorAll('[data-filter]').forEach(link => {
          if (link.dataset.filter === filter) link.setAttribute('aria-current', 'page');
          else link.removeAttribute('aria-current');
        });
        document.querySelector('#empty').hidden = visible.length > 0;
        document.querySelector('#empty-title').textContent = todos.length === 0 ? 'A fresh start.' : filter === 'active' ? 'All caught up.' : 'A little progress goes a long way.';
        document.querySelector('#empty-message').textContent = todos.length === 0 ? 'Add your first to-do and take it one thing at a time.' : filter === 'active' ? 'Nothing left on your list. Take a moment for yourself.' : 'Your completed to-dos will appear here.';
      }

      document.querySelector('#add-form').addEventListener('submit', event => {
        event.preventDefault();
        const title = input.value.trim();
        if (!title) {
          input.focus();
          return;
        }
        const id = typeof crypto.randomUUID === 'function' ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(36).slice(2)}`;
        todos.push({ id, title, completed: false });
        input.value = '';
        if (getFilter() === 'completed') location.hash = '/';
        save('Todo added.');
        input.focus();
      });
      toggleAll.addEventListener('change', () => {
        todos.forEach(todo => { todo.completed = toggleAll.checked; });
        save(toggleAll.checked ? 'All todos completed.' : 'All todos marked active.');
      });
      clearButton.addEventListener('click', () => {
        todos = todos.filter(todo => !todo.completed);
        save('Completed todos cleared.');
        input.focus();
      });
      window.addEventListener('hashchange', render);
      render();
    })();
  </script>
</body>
